import itertools
import numpy as np


class EliteTRSHADEv3:
    """
    Refinement of EliteTRSHADEv2:
    - Evaluation cache (no re-evaluation of duplicates).
    - JADE current-to-pbest/1 for continuous variables with external archive.
    - 1/5-style trust-region radius around the incumbent.
    - Discrete-combination coverage at initialisation (mixed-radix cover).
    - Exhaustive discrete-combination sweep around the incumbent when the
      discrete space is small (all combos at the incumbent's continuous part).
    - Per-coordinate continuous pattern search with step sizes that halve on failure,
      plus momentum extrapolation along the last successful incumbent move.
    - Elite archive restarts with shrinking populations.
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)
        self.pop_size = int(np.clip(4 * dim, 10, 48))
        self.H = 6
        self.stall_max = 10
        self.tr_prob = 0.3
        self.shrink = 0.75
        self.n_elite = 5
        self.max_combo_sweep = 64

    def __call__(self, func):
        rng = np.random.default_rng()
        d = self.dim
        lb = np.asarray(func.bounds.lb, dtype=float).copy()
        ub = np.asarray(func.bounds.ub, dtype=float).copy()
        vtypes = [str(t) for t in func.variable_types]

        cont = np.array([t == "continuous" for t in vtypes])
        disc = ~cont
        cat = np.array([t == "categorical" for t in vtypes])
        ordi = disc & ~cat
        nv = np.ones(d)
        for j in range(d):
            if disc[j]:
                nv[j] = ub[j] - lb[j] + 1.0
        span = np.maximum(ub - lb, 1e-12)
        n_combo = int(np.prod(nv[disc])) if disc.any() else 1
        dcols = np.where(disc)[0]
        ccols = np.where(cont)[0]

        # pattern-search step sizes for continuous coordinates (relative to span)
        pstep = np.full(d, 0.1)

        state = {"evals": 0, "best_y": np.inf, "best_x": None, "move": None}
        cache = {}
        xstore = {}
        tr = {"sigma": 0.05}

        def remaining():
            return self.budget - state["evals"]

        def repair(X):
            X = np.clip(X, lb, ub)
            if disc.any():
                X[:, disc] = np.clip(np.round(X[:, disc]), 0.0, nv[disc] - 1.0)
            return X

        def key(x):
            return tuple(np.round(x, 8))

        def evaluate(X):
            X = repair(np.array(X, dtype=float))
            n = len(X)
            Y = np.full(n, np.inf)
            if n == 0:
                return Y
            keys = [key(X[i]) for i in range(n)]
            new_idx = {}
            for i, k in enumerate(keys):
                if k in cache:
                    Y[i] = cache[k]
                elif k not in new_idx:
                    new_idx[k] = i
            if new_idx and remaining() > 0:
                idx = list(new_idx.values())[: remaining()]
                ys = np.asarray(func(X[idx]), dtype=float).reshape(-1)
                ys = np.nan_to_num(ys, nan=np.inf)
                state["evals"] += len(idx)
                for t, i in enumerate(idx):
                    cache[keys[i]] = ys[t]
                    xstore[keys[i]] = X[i].copy()
                    if ys[t] < state["best_y"]:
                        old = state["best_x"]
                        state["best_y"] = float(ys[t])
                        state["best_x"] = X[i].copy()
                        if old is not None:
                            state["move"] = state["best_x"] - old
            for i in range(n):
                if keys[i] in cache:
                    Y[i] = cache[keys[i]]
            return Y

        def elites(m):
            if not cache:
                return []
            items = sorted(cache.items(), key=lambda kv: kv[1])[:m]
            return [xstore[k] for k, _ in items]

        def init_lhs(n):
            X = np.empty((n, d))
            for j in range(d):
                if cont[j]:
                    u = (rng.permutation(n) + rng.random(n)) / n
                    X[:, j] = lb[j] + u * (ub[j] - lb[j])
            if disc.any():
                if n_combo <= n:
                    idx = rng.permutation(np.arange(n) % n_combo)
                    for j in dcols:
                        X[:, j] = idx % int(nv[j])
                        idx = idx // int(nv[j])
                else:
                    for j in dcols:
                        X[:, j] = rng.permutation(np.arange(n) % int(nv[j]))
            return repair(X)

        def combo_rows(x):
            """All discrete combinations with the continuous part of x fixed."""
            if not disc.any() or n_combo > self.max_combo_sweep:
                return []
            rows = []
            ranges = [range(int(nv[j])) for j in dcols]
            for vals in itertools.product(*ranges):
                y = x.copy()
                y[dcols] = np.asarray(vals, dtype=float)
                rows.append(y)
            return rows

        def neighbours(x):
            rows = []
            for j in dcols:
                if cat[j]:
                    for v in range(int(nv[j])):
                        if v != int(x[j]):
                            y = x.copy()
                            y[j] = v
                            rows.append(y)
                else:
                    for s in (-1.0, 1.0):
                        v = x[j] + s
                        if lb[j] <= v <= ub[j]:
                            y = x.copy()
                            y[j] = v
                            rows.append(y)
            # pattern search: per-coordinate steps
            for j in ccols:
                for s in (-1.0, 1.0):
                    for mult in (1.0, 0.1):
                        v = x[j] + s * mult * pstep[j] * span[j]
                        if lb[j] <= v <= ub[j]:
                            y = x.copy()
                            y[j] = v
                            rows.append(y)
            mv = state["move"]
            if mv is not None and np.any(mv != 0):
                for k in (0.5, 1.0, 2.0):
                    rows.append(repair((x + k * mv)[None, :])[0])
            return np.array(rows) if rows else np.empty((0, d))

        def sweep():
            while remaining() > 0 and state["best_x"] is not None:
                before = state["best_y"]
                x = state["best_x"]
                N = neighbours(x)
                C = combo_rows(x)
                parts = [A_ for A_ in (N, np.array(C) if C else np.empty((0, d))) if len(A_)]
                if not parts:
                    break
                N = np.vstack(parts)
                rng.shuffle(N)
                evaluate(N)
                if not state["best_y"] < before:
                    # failed: shrink pattern steps
                    pstep[ccols] *= 0.5
                    if np.all(pstep[ccols] < 1e-4) if len(ccols) else True:
                        pstep[ccols] = 0.1
                    break
                else:
                    # success: slightly enlarge pattern steps
                    pstep[ccols] = np.minimum(pstep[ccols] * 1.5, 0.2)

        def tr_moves(k):
            B = state["best_x"]
            U = np.tile(B, (k, 1))
            s = tr["sigma"] * np.exp(rng.uniform(-1.0, 0.0, (k, 1)))
            noise = rng.standard_normal((k, d))
            if len(ccols):
                U[:, cont] = B[cont] + s * span[cont] * noise[:, cont]
            if disc.any():
                flip = np.where(rng.random(k) < 0.5)[0]
                if len(flip):
                    jj = rng.choice(dcols, size=len(flip))
                    for r, j in zip(flip, jj):
                        if cat[j]:
                            U[r, j] = rng.integers(0, int(nv[j]))
                        else:
                            U[r, j] = B[j] + rng.choice([-1.0, 1.0])
            return repair(U)

        def restart_pop(n):
            el = elites(self.n_elite)
            if not el or rng.random() < 0.4:
                return init_lhs(n)
            w = np.arange(len(el), 0, -1, dtype=float)
            c = rng.choice(len(el), p=w / w.sum())
            B = el[c]
            X = np.tile(B, (n, 1))
            scales = tr["sigma"] * np.exp(rng.uniform(-2.0, 0.0, (n, 1)))
            nc = int(cont.sum())
            if nc > 0:
                X[:, cont] = B[cont] + scales * span[cont] * rng.standard_normal((n, nc))
            for i in range(1, n):
                flips = np.where(rng.random(d) < 0.25 * disc)[0]
                for j in flips:
                    if cat[j]:
                        X[i, j] = rng.integers(0, int(nv[j]))
                    else:
                        X[i, j] = B[j] + rng.choice([-1.0, 1.0])
            return repair(X)

        restart_id = 0
        while remaining() > 0:
            base = max(6, int(round(self.pop_size * self.shrink ** restart_id)))
            NP = min(base, remaining())
            restart_id += 1

            X = restart_pop(NP)
            el = elites(min(3, NP))
            for i, e in enumerate(el):
                if i < len(X):
                    X[i] = e
            if state["best_x"] is not None and len(X) > 0:
                X[0] = state["best_x"]
            Y = evaluate(X)
            if remaining() <= 0 and not np.isfinite(Y).any():
                break

            A = np.empty((0, d))
            MF = np.full(self.H, 0.5)
            MCR = np.full(self.H, 0.5)
            mpos = 0
            stall = 0
            gbest = np.min(Y)
            succ_hist = []

            while remaining() > 0:
                n = len(X)
                spread = np.std(X, axis=0) / span
                if stall >= self.stall_max or np.all(spread < 1e-3):
                    break

                m = min(n, remaining())
                r = rng.integers(0, self.H, n)
                F = np.clip(MF[r] + 0.1 * rng.standard_cauchy(n), 0.1, 1.0)
                CR = np.clip(MCR[r] + 0.1 * rng.standard_normal(n), 0.0, 1.0)
                Fc = F[:, None]

                order = np.argsort(Y)
                p = max(2, int(0.15 * n))
                pb = order[rng.integers(0, p, n)]
                pool = X if len(A) == 0 else np.vstack([X, A])
                r1 = rng.permutation(n)
                r2 = rng.integers(0, len(pool), n)
                Xpb, Xr1, Xr2 = X[pb], X[r1], pool[r2]

                V = X.copy()
                cmut = X + Fc * (Xpb - X) + Fc * (Xr1 - Xr2)
                V[:, cont] = cmut[:, cont]

                if ordi.any():
                    ostep = np.round(Fc * (Xpb - X))
                    rnd = (rng.random((n, d)) < 0.1) * rng.choice([-1.0, 1.0], (n, d))
                    V[:, ordi] = (X + ostep + rnd)[:, ordi]

                if cat.any():
                    donor = np.where(rng.random((n, d)) < 0.5, Xpb, Xr1)
                    V[:, cat] = donor[:, cat]
                    mutc = (rng.random((n, d)) < 0.1) & cat[None, :]
                    cols = np.where(mutc)[1]
                    if len(cols):
                        V[mutc] = np.floor(rng.random(len(cols)) * nv[cols])

                mask = rng.random((n, d)) < CR[:, None]
                mask[np.arange(n), rng.integers(0, d, n)] = True
                U = np.where(mask, V, X)

                tridx = np.array([], dtype=int)
                if state["best_x"] is not None:
                    tridx = np.where(rng.random(n) < self.tr_prob)[0]
                    if len(tridx):
                        U[tridx] = tr_moves(len(tridx))

                U = repair(U[:m])
                best_before = state["best_y"]
                Yu = np.asarray(evaluate(U))[:m]

                Yc = Y[:m]
                better = Yu <= Yc
                imp = Yu < Yc

                if imp.any():
                    w = np.abs(Yc - Yu)[imp]
                    w = np.nan_to_num(w, nan=1.0, posinf=1.0) + 1e-12
                    w = w / w.sum()
                    Fi = F[:m][imp]
                    CRi = CR[:m][imp]
                    MF[mpos] = np.sum(w * Fi ** 2) / max(np.sum(w * Fi), 1e-12)
                    MCR[mpos] = np.sum(w * CRi)
                    mpos = (mpos + 1) % self.H

                rep = np.where(better & imp)[0]
                if len(rep):
                    A = np.vstack([A, X[rep]]) if len(A) else X[rep].copy()
                    if len(A) > n:
                        keep = rng.choice(len(A), n, replace=False)
                        A = A[keep]

                Xv = X[:m]
                Xv[better] = U[better]
                Yc[better] = Yu[better]

                improved_global = state["best_y"] < best_before
                if len(tridx):
                    succ_hist.append(1.0 if improved_global else 0.0)
                    if len(succ_hist) >= 5:
                        rate = np.mean(succ_hist[-5:])
                        if rate > 0.2:
                            tr["sigma"] = min(tr["sigma"] * 1.5, 0.3)
                        else:
                            tr["sigma"] = max(tr["sigma"] * 0.85, 1e-4)

                if improved_global:
                    sweep()

                if np.min(Y) < gbest - 1e-12:
                    gbest = np.min(Y)
                    stall = 0
                else:
                    stall += 1

        return state["best_y"], state["best_x"]
